#include "../../core/runtime/runtime.h"

/* Generated by Phase B of #06.75: carved from runtime.c.
   DO NOT add to this file unless you also update the top-level runtime.c #include order. */

void ruxen_thread_sleep_ns(int64_t ns) {
    if (ns <= 0) {
        return;
    }

    struct timespec req;
    req.tv_sec = (time_t)(ns / 1000000000LL);
    req.tv_nsec = (long)(ns % 1000000000LL);

    while (nanosleep(&req, &req) == -1 && errno == EINTR) {
    }
}

/* Forward decl into library/std/future/runtime/reactor.c. Sub-phase
 * 4A: `Thread.yield_now` now drives the per-thread reactor's wait
 * point when registrations are pending (block_on's Pending arm
 * routes here unchanged via the existing AST emission in
 * async_lowering::build_block_on_loop). If no reactor is installed
 * on the current thread, or the reactor has no registrations, the
 * call falls back to sched_yield — matches pre-4A behaviour for any
 * non-async-I/O caller of Thread.yield_now. */
void ruxen_reactor_park_current(void);

void ruxen_thread_yield(void) {
    ruxen_reactor_park_current();
}
/* ---------------------------------------------------------------------
 * std::time
 *
 * Two clock sources, both returned as nanoseconds in an int64_t.
 *
 *   - `ruxen_time_now_ns`  → monotonic clock, suitable for measuring
 *     elapsed time. Never moves backwards. Anchor is unspecified — only
 *     differences are meaningful.
 *
 *   - `ruxen_time_unix_ns` → realtime clock, nanoseconds since the Unix
 *     epoch (1970-01-01 UTC). Subject to NTP adjustments and manual
 *     clock changes; do not use for measuring elapsed time.
 *
 * Both clamp to 0 on clock_gettime failure (which is effectively never
 * on Linux/macOS but the contract has to say something). Returning 0
 * keeps the type signature simple — no Result wrapping for a syscall
 * that has no failure mode in practice.
 * --------------------------------------------------------------------- */
int64_t ruxen_time_now_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (int64_t)ts.tv_sec * 1000000000LL + (int64_t)ts.tv_nsec;
}

int64_t ruxen_time_unix_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return 0;
    }
    return (int64_t)ts.tv_sec * 1000000000LL + (int64_t)ts.tv_nsec;
}

/* ---------------------------------------------------------------------
 * std::time::Duration / std::time::Instant + std::thread::sleep
 *
 * Phase 2 stdlib (#06.5 T4) — scalar-wrapper classes around int64_t
 * nanoseconds.
 *
 *   - RuxenDuration  = { int64_t nanos }            (8 bytes)
 *   - RuxenInstant   = { int64_t monotonic_nanos }  (8 bytes)
 *
 * Both are flat POD heap structs: no inner pointers, no resource
 * ownership. The MIR scope-exit drop pipeline emits the default
 * `ruxen_dealloc` for any local of type Duration / Instant — neither
 * needs an entry in `user_drop_classes` (no `_drop` helper required).
 *
 * Operator overloads
 *   The language has no general user-side `+`/`-` overload mechanism;
 *   built-in types get hard-coded special-cases in
 *   `mir/lower/expr/binops.rs` (String concat, Vec/Map/Set equality,
 *   etc.). We follow that pattern — `Duration + Duration`,
 *   `Duration - Duration`, and `Instant - Instant` route to the
 *   `ruxen_duration_add` / `ruxen_duration_sub` / `ruxen_instant_sub`
 *   helpers below. The named `.add()` / `.sub()` methods are wired in
 *   parallel as the path that survives generic code where the binop
 *   isn't statically resolved.
 *
 * Saturation
 *   `ruxen_duration_sub(a, b)` saturates to zero when `a < b` — the
 *   public contract is "Duration is non-negative". Add overflow
 *   triggers `ruxen_panic("Duration arithmetic overflow")`; matches the
 *   "panic on representation overflow" stance from
 *   `ruxen_int_to_string` and friends.
 *
 * Instant ordering
 *   `ruxen_instant_duration_since(self, earlier)` panics if
 *   `earlier > self`. This is the documented Rust-style contract — a
 *   monotonic clock that goes backwards is a programmer error, not an
 *   I/O failure, so no Result wrapping.
 * --------------------------------------------------------------------- */

#define RUXEN_NS_PER_SEC   1000000000LL
#define RUXEN_NS_PER_MILLI 1000000LL
#define RUXEN_NS_PER_MICRO 1000LL

/* RuxenDuration struct body lives in runtime.h so net/tcp.c can read
 * `->nanos` when wiring SO_RCVTIMEO / SO_SNDTIMEO. RuxenInstant is
 * declared opaque in runtime.h; we promote it here to a full
 * definition for the time.c-internal helpers below. Pinned size
 * checks remain. */
typedef struct RuxenInstant {
    int64_t monotonic_nanos;
} RuxenInstant;

_Static_assert(sizeof(RuxenDuration) == 8,
    "RuxenDuration wire layout drifted from documented 8-byte form");

_Static_assert(sizeof(RuxenInstant) == 8,
    "RuxenInstant wire layout drifted from documented 8-byte form");

static RuxenDuration *ruxen_duration_alloc(int64_t nanos) {
    RuxenDuration *d = (RuxenDuration *)ruxen_alloc(sizeof(RuxenDuration));
    d->nanos = nanos;
    return d;
}

static RuxenInstant *ruxen_instant_alloc(int64_t monotonic_nanos) {
    RuxenInstant *i = (RuxenInstant *)ruxen_alloc(sizeof(RuxenInstant));
    i->monotonic_nanos = monotonic_nanos;
    return i;
}

/* `from_secs(s)` — multiply guarded against signed int64 overflow.
 * The boundary is `INT64_MAX / NS_PER_SEC` (~292 years) on the
 * positive side and `INT64_MIN / NS_PER_SEC` on the negative.
 * Beyond that, panic — the alternative is silent UB on signed
 * overflow which is unacceptable for a stdlib clock primitive. */
RuxenDuration *ruxen_duration_from_secs(int64_t s) {
    if (s > INT64_MAX / RUXEN_NS_PER_SEC || s < INT64_MIN / RUXEN_NS_PER_SEC) {
        ruxen_panic("Duration.from_secs overflow");
    }
    return ruxen_duration_alloc(s * RUXEN_NS_PER_SEC);
}

RuxenDuration *ruxen_duration_from_millis(int64_t ms) {
    if (ms > INT64_MAX / RUXEN_NS_PER_MILLI || ms < INT64_MIN / RUXEN_NS_PER_MILLI) {
        ruxen_panic("Duration.from_millis overflow");
    }
    return ruxen_duration_alloc(ms * RUXEN_NS_PER_MILLI);
}

RuxenDuration *ruxen_duration_from_micros(int64_t us) {
    if (us > INT64_MAX / RUXEN_NS_PER_MICRO || us < INT64_MIN / RUXEN_NS_PER_MICRO) {
        ruxen_panic("Duration.from_micros overflow");
    }
    return ruxen_duration_alloc(us * RUXEN_NS_PER_MICRO);
}

RuxenDuration *ruxen_duration_from_nanos(int64_t ns) {
    return ruxen_duration_alloc(ns);
}

/* ruxen_duration_as_{secs,millis,micros,nanos} deleted in task #27 /
 * #19: Duration is now `layout c; nanos: Int` on the Ruxen side, so
 * `def as_nanos -> Int; self.nanos; end` reads the field directly.
 * See library/std/time/src/lib.rx. */

/* Checked sum: panic on int64 overflow. Mirrors Rust's
 * `Duration::checked_add` returning None — we don't ship Option-of-
 * Duration yet, so the contract is "panic" instead. */
RuxenDuration *ruxen_duration_add(RuxenDuration *a, RuxenDuration *b) {
    if (!a || !b) {
        ruxen_panic("Duration.+ on null receiver");
    }
    int64_t x = a->nanos;
    int64_t y = b->nanos;
    if (((y > 0) && (x > INT64_MAX - y)) || ((y < 0) && (x < INT64_MIN - y))) {
        ruxen_panic("Duration addition overflow");
    }
    return ruxen_duration_alloc(x + y);
}

/* Saturating subtract: result clamps to zero on `a < b`. This is the
 * Duration-is-non-negative contract; underflow on a clock primitive
 * almost always means "the elapsed time hasn't passed yet" and a
 * zero is the unambiguous neutral value. */
RuxenDuration *ruxen_duration_sub(RuxenDuration *a, RuxenDuration *b) {
    if (!a || !b) {
        ruxen_panic("Duration.- on null receiver");
    }
    int64_t x = a->nanos;
    int64_t y = b->nanos;
    if (x <= y) {
        return ruxen_duration_alloc(0);
    }
    return ruxen_duration_alloc(x - y);
}

/* CLOCK_MONOTONIC sample. Returns 0 on clock_gettime failure (the
 * same contract as `ruxen_time_now_ns` — there's no documented
 * failure path on Linux/macOS in practice). */
RuxenInstant *ruxen_instant_now(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return ruxen_instant_alloc(0);
    }
    return ruxen_instant_alloc((int64_t)ts.tv_sec * RUXEN_NS_PER_SEC + (int64_t)ts.tv_nsec);
}

RuxenDuration *ruxen_instant_elapsed(RuxenInstant *t) {
    if (!t) {
        ruxen_panic("Instant.elapsed on null receiver");
    }
    struct timespec ts;
    int64_t now_ns;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        now_ns = t->monotonic_nanos;
    } else {
        now_ns = (int64_t)ts.tv_sec * RUXEN_NS_PER_SEC + (int64_t)ts.tv_nsec;
    }
    if (now_ns < t->monotonic_nanos) {
        /* Monotonic clock contract guarantees this can't happen, but if
         * the kernel ever lies, surface zero rather than a negative. */
        return ruxen_duration_alloc(0);
    }
    return ruxen_duration_alloc(now_ns - t->monotonic_nanos);
}

/* `self.duration_since(earlier)` — panics if `earlier > self`.
 * Same semantics drives `Instant - Instant`. */
RuxenDuration *ruxen_instant_duration_since(RuxenInstant *self, RuxenInstant *earlier) {
    if (!self || !earlier) {
        ruxen_panic("Instant.duration_since on null receiver");
    }
    if (earlier->monotonic_nanos > self->monotonic_nanos) {
        ruxen_panic("Instant.duration_since: earlier is in the future");
    }
    return ruxen_duration_alloc(self->monotonic_nanos - earlier->monotonic_nanos);
}

RuxenDuration *ruxen_instant_sub(RuxenInstant *a, RuxenInstant *b) {
    /* Same semantics as duration_since(a, b). */
    return ruxen_instant_duration_since(a, b);
}

/* Thin wrapper that unpacks a `Duration *` and delegates to the
 * existing `ruxen_thread_sleep_ns(int64)`. The latter's signature
 * stays untouched — the v1 `Thread.sleep(int)` static method still
 * calls it directly. */
void ruxen_thread_sleep_duration(RuxenDuration *d) {
    if (!d) {
        return;
    }
    ruxen_thread_sleep_ns(d->nanos);
}
